    steg2        : INT := 0;
    xRobot1      : BOOL := FALSE;
    xRobot2      : BOOL := FALSE;
    trigReset    : R_TRIG;
    xLarm        : BOOL := FALSE;
    xKravOmstart : BOOL := TRUE;
    xDrift       : BOOL := FALSE;
    xStart1      : BOOL := FALSE; (* maskin 1:s begaran om roboten *)
    xStart2      : BOOL := FALSE; (* maskin 2:s begaran om roboten *)
END_VAR

trigReset(CLK := SYS_RESET);

IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;

