                ST560_DOR_OPEN := FALSE;
                steg1 := 5;
            END_IF;
        5:
            IF NOT ST560_DOR_OPENED THEN
                ST560_CYC_START := TRUE;
                xRobot1 := FALSE;
                steg1 := 6;
            END_IF;
        6:
            IF ST560_SPN_RUN THEN
                ST560_CYC_START := FALSE;
                steg1 := 0;
            END_IF;
    ELSE
        steg1 := 0;
    END_CASE;

    (* Maskin 2, samma kedja mot samma robot. *)
    CASE steg2 OF
        0:
            ST570_CHK_CLAMP := TRUE;
            IF ST570_CYC_DONE AND NOT ST570_SPN_RUN AND ST560_PRT_PRS
               AND NOT xRobot1 THEN
                xRobot2 := TRUE;
                ST570_DOR_OPEN := TRUE;
                steg2 := 1;
            END_IF;
        1:
            IF ST570_DOR_OPENED AND NOT ST570_SPN_RUN THEN
                ST570_CHK_CLAMP := FALSE;
                steg2 := 2;
            END_IF;
        2:
            IF NOT ST570_CHK_CLAMPED THEN
                xStart2 := TRUE;
                steg2 := 3;
            END_IF;
        3:
            IF ST560_RB_DONE THEN
                xStart2 := FALSE;
                ST570_CHK_CLAMP := TRUE;
                steg2 := 4;
            END_IF;
        4:
            IF ST570_CHK_CLAMPED THEN
                ST570_DOR_OPEN := FALSE;
                steg2 := 5;
            END_IF;
        5:
            IF NOT ST570_DOR_OPENED THEN
                ST570_CYC_START := TRUE;
                xRobot2 := FALSE;
                steg2 := 6;
            END_IF;
        6:
            IF ST570_SPN_RUN THEN
                ST570_CYC_START := FALSE;
                steg2 := 0;
            END_IF;
