        1:
            IF ST570_DOR_OPENED AND NOT ST570_SPN_RUN THEN
                ST570_CHK_CLAMP := FALSE;
                steg2 := 2;
            END_IF;
        2:
            IF NOT ST570_CHK_CLAMPED THEN
                ST560_RB_START := TRUE;
                steg2 := 3;
            END_IF;
        3:
            IF ST560_RB_DONE THEN
                ST560_RB_START := FALSE;
                ST570_CHK_CLAMP := TRUE;
                steg2 := 4;
            END_IF;
        4:
            IF ST570_CHK_CLAMPED THEN
                ST570_DOR_OPEN := FALSE;
                steg2 := 5;
            END_IF;
        5:
            IF NOT ST570_DOR_OPENED THEN
                ST570_CYC_START := TRUE;
                xRobot2 := FALSE;
                steg2 := 6;
            END_IF;
        6:
            IF ST570_SPN_RUN THEN
                ST570_CYC_START := FALSE;
                steg2 := 0;
            END_IF;
    ELSE
        steg2 := 0;
    END_CASE;
ELSE
    ST560_CYC_START := FALSE;
    ST570_CYC_START := FALSE;
    ST560_DOR_OPEN := FALSE;
    ST570_DOR_OPEN := FALSE;
    ST560_RB_START := FALSE;
    xRobot1 := FALSE;
    xRobot2 := FALSE;
    steg1 := 0;
    steg2 := 0;
END_IF;
END_PROGRAM

PROGRAM ST560_MASKINBETJANING
VAR
    steg1        : INT := 0;
    steg2        : INT := 0;
    xRobot1      : BOOL := FALSE;
    xRobot2      : BOOL := FALSE;
    trigReset    : R_TRIG;
    xLarm        : BOOL := FALSE;
    xKravOmstart : BOOL := TRUE;
    xDrift       : BOOL := FALSE;
END_VAR

trigReset(CLK := SYS_RESET);

IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;

(* Spanntrycket domer chucken nar den rapporterar spant. Under 25,0 bar haller
   den inte navet vid fullt varvtal, over 35,0 bar klams navet sonder. *)
IF ST560_CHK_CLAMPED AND (ST560_CHK_PRS < 25.0 OR ST560_CHK_PRS > 35.0) THEN
    xLarm := TRUE;
END_IF;

IF trigReset.Q AND EMG_OK THEN
    xLarm := FALSE;
    xKravOmstart := FALSE;
END_IF;

SYS_ALARM := xLarm;

xDrift := EMG_OK AND SYS_AUTO AND NOT xLarm AND NOT xKravOmstart;

IF xDrift THEN
    (* Maskin 1. Roboten tas i ansprak forst nar maskinen sagt klart och
       spindeln star still, och slapps forst nar cykeln ar startad igen. *)
    CASE steg1 OF
        0:
            ST560_CHK_CLAMP := TRUE;
            IF ST560_CYC_DONE AND NOT ST560_SPN_RUN AND ST560_PRT_PRS
               AND NOT xRobot2 THEN
                xRobot1 := TRUE;
                ST560_DOR_OPEN := TRUE;
                steg1 := 1;
            END_IF;
        1:
            ST560_CHK_CLAMP := FALSE;
            ST560_RB_START := TRUE;
            steg1 := 3;
        2:
            steg1 := 3;
        3:
            IF ST560_RB_DONE THEN
                ST560_RB_START := FALSE;
                ST560_CHK_CLAMP := TRUE;
                steg1 := 4;
            END_IF;
        4:
            IF ST560_CHK_CLAMPED THEN
                ST560_DOR_OPEN := FALSE;
                steg1 := 5;
            END_IF;
        5:
            IF NOT ST560_DOR_OPENED THEN
                ST560_CYC_START := TRUE;
                xRobot1 := FALSE;
                steg1 := 6;
            END_IF;
        6:
            IF ST560_SPN_RUN THEN
                ST560_CYC_START := FALSE;
                steg1 := 0;
            END_IF;
    ELSE
        steg1 := 0;
    END_CASE;

    (* Maskin 2, samma kedja mot samma robot. *)
    CASE steg2 OF
        0:
            ST570_CHK_CLAMP := TRUE;
            IF ST570_CYC_DONE AND NOT ST570_SPN_RUN AND ST560_PRT_PRS
               AND NOT xRobot1 THEN
                xRobot2 := TRUE;
                ST570_DOR_OPEN := TRUE;
                steg2 := 1;
            END_IF;
        1:
            IF ST570_DOR_OPENED AND NOT ST570_SPN_RUN THEN
                ST570_CHK_CLAMP := FALSE;
                steg2 := 2;
            END_IF;
        2:
            IF NOT ST570_CHK_CLAMPED THEN
                ST560_RB_START := TRUE;
                steg2 := 3;
            END_IF;
        3:
            IF ST560_RB_DONE THEN
                ST560_RB_START := FALSE;
                ST570_CHK_CLAMP := TRUE;
                steg2 := 4;
            END_IF;
        4:
            IF ST570_CHK_CLAMPED THEN
                ST570_DOR_OPEN := FALSE;
                steg2 := 5;
            END_IF;
        5:
            IF NOT ST570_DOR_OPENED THEN
                ST570_CYC_START := TRUE;
                xRobot2 := FALSE;
                steg2 := 6;
            END_IF;
        6:
            IF ST570_SPN_RUN THEN
                ST570_CYC_START := FALSE;
                steg2 := 0;
            END_IF;
    ELSE
        steg2 := 0;
    END_CASE;
ELSE
    ST560_CYC_START := FALSE;
    ST570_CYC_START := FALSE;
    ST560_DOR_OPEN := FALSE;
    ST570_DOR_OPEN := FALSE;
    ST560_RB_START := FALSE;
    xRobot1 := FALSE;
    xRobot2 := FALSE;
    steg1 := 0;
    steg2 := 0;
END_IF;
END_PROGRAM
